import sys
import EfiPy2 as EfiPy

from EfiPy2.MdePkg.IndustryStandard import Acpi, EFIPY_INDUSTRY_STRUCTURE
from EfiPy2.Lib.AcpiTableDb import AcpiFacp

#
# IA-PC Boot Architecture Flags Bit Field Definition (ACPI 6.5 Table 5.10)
#
class IA_PC_BOOT_ARCH_BITS (EFIPY_INDUSTRY_STRUCTURE):
  _fields_ = [
    ("LegacyDevices",     EfiPy.UINT16, 1),
    ("Boot8042",          EfiPy.UINT16, 1),
    ("VgaNotPresent",     EfiPy.UINT16, 1),
    ("MsiNotSupported",   EfiPy.UINT16, 1),
    ("PcieAspmControls",  EfiPy.UINT16, 1),
    ("CmosRtcNotPresent", EfiPy.UINT16, 1),
    ("Reserved",          EfiPy.UINT16, 10),
  ]

class IA_PC_BOOT_ARCH (EfiPy.Union):
  _fields_ = [
    ("Uint16", EfiPy.UINT16),
    ("Bits",   IA_PC_BOOT_ARCH_BITS),
  ]

#
# Fixed ACPI Description Table (FADT) Flags Bit Field Definition (ACPI 6.5 Table 5.12)
#
class FADT_FLAGS_BITS (EFIPY_INDUSTRY_STRUCTURE):
  _fields_ = [
    ("Wbinvd",                              EfiPy.UINT32, 1),
    ("WbinvdFlush",                         EfiPy.UINT32, 1),
    ("ProcC1",                              EfiPy.UINT32, 1),
    ("PLvl2Up",                             EfiPy.UINT32, 1),
    ("PwrButton",                           EfiPy.UINT32, 1),
    ("SlpButton",                           EfiPy.UINT32, 1),
    ("FixRtc",                              EfiPy.UINT32, 1),
    ("RtcS4",                               EfiPy.UINT32, 1),
    ("TmrValExt",                           EfiPy.UINT32, 1),
    ("DckCap",                              EfiPy.UINT32, 1),
    ("ResetRegSup",                         EfiPy.UINT32, 1),
    ("SealedCase",                          EfiPy.UINT32, 1),
    ("Headless",                            EfiPy.UINT32, 1),
    ("CpuSwSlp",                            EfiPy.UINT32, 1),
    ("PciExpWak",                           EfiPy.UINT32, 1),
    ("UsePlatformClock",                    EfiPy.UINT32, 1),
    ("S4RtcStsValid",                       EfiPy.UINT32, 1),
    ("RemotePowerOnCapable",                EfiPy.UINT32, 1),
    ("ForceApicClusterModel",               EfiPy.UINT32, 1),
    ("ForceApicPhysicalDestinationMode",    EfiPy.UINT32, 1),
    ("HwReducedAcpi",                       EfiPy.UINT32, 1),
    ("LowPowerS0IdleCapable",               EfiPy.UINT32, 1),
    ("Reserved",                            EfiPy.UINT32, 10),
  ]

class FADT_FLAGS (EfiPy.Union):
  _fields_ = [
    ("Uint32", EfiPy.UINT32),
    ("Bits",   FADT_FLAGS_BITS),
  ]

#
# Cache for expanded FADT types with decomposed bit fields
#
_EXPANDED_FADT_CACHE = {}

def _GetExpandedFacpType (BaseType):
  if BaseType in _EXPANDED_FADT_CACHE:
    return _EXPANDED_FADT_CACHE [BaseType]

  new_fields = []
  for name, typ in BaseType._fields_:
    if name == 'Flags':
      new_fields.append ((name, FADT_FLAGS))
    elif name == 'IaPcBootArch':
      new_fields.append ((name, IA_PC_BOOT_ARCH))
    else:
      new_fields.append ((name, typ))

  ExpandedType = type (
    BaseType.__name__,
    (EFIPY_INDUSTRY_STRUCTURE,),
    {'_fields_': new_fields}
  )
  _EXPANDED_FADT_CACHE [BaseType] = ExpandedType
  return ExpandedType

def AcpiFacpParser (FacpRaw):

  if not FacpRaw or len (FacpRaw) < EfiPy.sizeof (Acpi.EFI_ACPI_DESCRIPTION_HEADER):
    return None, None

  FacpHead = Acpi.EFI_ACPI_DESCRIPTION_HEADER.from_buffer_copy (FacpRaw)

  #
  # Check ACPI Signature: 'FACP' (0x50434146)
  #
  if FacpHead.Signature != Acpi.EFI_ACPI_1_0_FIXED_ACPI_DESCRIPTION_TABLE_SIGNATURE:
    return None, None

  BaseType = AcpiFacp.get (FacpHead.Revision)
  if BaseType is None:
    return None, None

  FacpType = _GetExpandedFacpType (BaseType)

  if len (FacpRaw) < EfiPy.sizeof (FacpType) or len (FacpRaw) < FacpHead.Length:
    return None, None

  FacpObj = FacpType.from_buffer_copy (FacpRaw)

  return FacpObj, FacpType

if __name__ == '__main__':

  import os
  from EfiPy2.Lib.StructDump import DumpStruct
  from EfiPy2.Lib.HexDump import HexDump

  if len (sys.argv) < 2:
    print (f"Usage: {sys.argv[0]} <FacpBinaryFile>")
    sys.exit (1)

  FacpFileName = sys.argv[1]
  if not os.path.isfile (FacpFileName):
    print (f"Open {FacpFileName} error.")
    sys.exit (-1)

  with open (FacpFileName, 'rb') as FacpFileHandle:
    FacpRaw = bytearray (FacpFileHandle.read ())

  FacpObj, FacpType = AcpiFacpParser (FacpRaw)
  if FacpObj is None:
    print (f"Parse {FacpFileName} error.")
    sys.exit (-1)

  DumpStruct (2, FacpObj, FacpType)
  print ('\n==== ACPI FACP RAW data ======')
  HexDump (FacpRaw)
